css:
@font-face {
  font-family: 'Certificate';
  src: url("/assets/lms/css/forte.ttf");
  font-weight: bold;
}

@font-face {
  font-family: 'heading';
  src: url("/assets/lms/css/Castellar_Regular.ttf");
  font-weight: normal;
}

body {
  margin: 0;
  padding: 0;
}

.certificate-format {
  width: 1123px;
  height: 750px;
  margin: 0 auto;
  position: relative;
  page-break-after: always;
  background-size: cover;
}

.inner-border {
  width: 100%;
  height: 100%;
  position: relative;
  font-family: 'Calibri', sans-serif;
  color: #000;
}

.logo {
  position: absolute;
  top: 10px;
  left: -10px;
  width: 200px;
}

.cert-number {
  position: absolute;
  top: 50px;
  right: 50px;
  font-size: 12px;
  color: black;
  text-align: right;
}

.cert-label {
  color: grey;
}

.cert-value {
  color: black;
  font-weight: bold;
}

.title {
  position: absolute;
  top: 220px;
  width: 100%;
  text-align: center;
  font-size: 34px;
  font-family: 'heading';
  letter-spacing: 1px;
}

.top-divider{ 
  position: absolute;
  top: 247px;
  left: 180px;
  width: 760px;
  border: none;
  border-top: 1.5px solid #000;
}

.subtitle {
  position: absolute;
  top: 273px;
  width: 100%;
  text-align: center;
  font-size: 1rem;
  font-family: 'heading'; /* ✅ same as title */
  font-weight: normal;
  color: black;
  text-transform: uppercase;
}

.member-name {
  position: absolute;
  top: 348px;
  width: 100%;
  text-align: center;
  font-size: 42px;
  font-family: 'Certificate';
  font-weight: bold;
}

.top-certificate-divider {
  position: absolute;
  top: 380px;
  left: 180px;
  width: 760px;
  border: none;
  border-top: 1.5px solid #000;
}

.course-text {
  position: absolute;
  top: 410px;
  width: 100%;
  text-align: center;
  font-size: 21px;
  line-height: 1.6;
  padding: 0 80px;
}

.signature-left,
.signature-center,
.signature-right {
  position: absolute;
  bottom: 40px;
  width: 200px;
  text-align: center;
  font-size: 20px;
  font-family: 'Certificate';
}

.signature-left {
  left: 80px;
}

.signature-center {
  left: 50%;
  transform: translateX(-50%);
}

.signature-right {
  right: 80px;
}

.signature-name {
  font-weight: bold;
  margin-top: 5px;
  /*margin-left: -21px;*/
  margin-left: 5px;
}

.signature-role {
  font-size: 16px;
  color:grey;
  font-family: 'Calibri', sans-serif;
}

.footer-divider {
  border: none;
  border-top: 1px solid #000;
  width: 140px;
  margin: 5px auto;
}
